def is_convex_polygon(points):
    n = len(points)
    if n < 3:
        return False
    # Sort the points in counter-clockwise order
    points = sorted(points)
    # Check all consecutive triplets
    for i in range(n):
        a = points[i]
        b = points[(i+1)%n]
        c = points[(i+2)%n]
        if cross(a, b, c) < 0:
            return False
    return True

def point_in_polygon(p, polygon):
    n = len(polygon)
    wn = 0
