        x1, y1 = polygon[i]
        x2, y2 = polygon[(i+1)%n]
        if y1 <= p[1]:
            if y2 > p[1]:
                if (p[0] - x1) * (y2 - y1) < (x2 - x1) * (p[1] - y1):
